(function () {"use strict";
function syncThemeColor() {var meta = document.querySelector('meta[name="theme-color"]'); if (!meta) return; var c = getComputedStyle(document.documentElement).getPropertyValue("--theme-color").trim(); if (c) meta.setAttribute("content", c);}
function syncTheme() {var theme = document.documentElement.getAttribute("data-theme") ||"light"; document.querySelectorAll(".theme-toggle button").forEach(function (btn) {btn.setAttribute("aria-pressed", btn.getAttribute("data-theme") === theme ?"true":"false");}); syncThemeColor();} var toggle = document.querySelector(".theme-toggle"); if (toggle) {toggle.addEventListener("click", function (e) {var btn = e.target.closest("button[data-theme]"); if (!btn) return; var theme = btn.getAttribute("data-theme"); document.documentElement.setAttribute("data-theme", theme); try {localStorage.setItem("shpato-theme", theme);} catch (err) {} syncTheme();});}
function syncShareLinks() {var canonical = document.querySelector('link[rel="canonical"]'); var url = (canonical && canonical.href) || location.href; var u = encodeURIComponent(url); var title = document.title; var hrefs = {
"share-x":"https://twitter.com/intent/tweet?text=" + encodeURIComponent(title) +"&url=" + u,"share-facebook":"https://www.facebook.com/sharer/sharer.php?u=" + u,"share-linkedin":"https://www.linkedin.com/sharing/share-offsite/?url=" + u,
"share-bluesky":"https://bsky.app/intent/compose?text=" + encodeURIComponent(title +" " + url)
}; Object.keys(hrefs).forEach(function (id) {var link = document.getElementById(id); if (link) link.href = hrefs[id];});}
function syncPanCue(wrap) {var frame = wrap.closest(".table-frame"); if (!frame) return; var max = wrap.scrollWidth - wrap.clientWidth; var sides = []; if (max > 1) {if (wrap.scrollLeft > 0) sides.push("left"); if (wrap.scrollLeft < max - 1) sides.push("right");} if (sides.length) frame.setAttribute("data-pan", sides.join(" ")); else frame.removeAttribute("data-pan");} function syncPanCues() {document.querySelectorAll(".table-frame > .table-wrap").forEach(syncPanCue);} document.querySelectorAll(".table-frame > .table-wrap").forEach(function (wrap) {wrap.addEventListener("scroll", function () {syncPanCue(wrap);}, {passive: true});}); window.addEventListener("resize", syncPanCues);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(syncPanCues); syncTheme(); syncShareLinks(); syncPanCues();})();
